function доходности(цены) {
  const результат = [];
  for (let индекс = 1; индекс < цены.length; индекс++) {
    if (цены[индекс - 1] === 0) результат.push(null);
    else результат.push(цены[индекс] / цены[индекс - 1] - 1);
  }
  return результат;
}
console.log(доходности([100, 110, 99]));
